pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        amount = bound(amount, 1, type(uint128).max);
        uint256 before = c.balances(actor);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        assertEq(c.balances(actor), before + amount);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, LogFile} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    LogFile log;

    function setUp() public {
        c = new C();
        log = new LogFile();
        c.SetLogFile(address(log));
        c.SetMinSum(0);
        c.Initialized();
    }

    function testFuzz_property(address actor, uint256 amount1, uint256 amount2) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        uint256 cap = type(uint256).max / 3;
        amount1 = bound(amount1, 0, cap);
        amount2 = bound(amount2, 0, cap);

        vm.deal(actor, amount1 + amount2);
        vm.prank(actor);
        c.Deposit{value: amount1}();
        vm.prank(actor);
        c.Deposit{value: amount2}();

        // General rule: recorded balances exactly track deposited ether.
        assertTrue(c.balances(actor) == amount1 + amount2);
    }
}

